DECLARE
  actual_address INET := inet_server_addr();
  actual_port INTEGER := inet_server_port();
BEGIN
  PERFORM "phase7_require_caller_role"('nihongo_phase7_migration');
  IF expected_database IS NULL OR expected_database <> current_database()
    OR actual_address IS NULL OR expected_server_address IS NULL
    OR expected_server_address IS DISTINCT FROM actual_address
    OR expected_server_port IS DISTINCT FROM actual_port
    OR expected_server_port NOT BETWEEN 1 AND 65535
    OR (environment_value = 'TEST' AND expected_database !~ '_test$')
    OR (environment_value = 'DEVELOPMENT' AND expected_database !~ '_dev$') THEN
    RAISE EXCEPTION 'Phase 7 database capability does not match the safe target.'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO "Phase7DatabaseCapability" (
    "id", "databaseName", "serverAddress", "serverPort", "environment",
    "registeredAt"
  ) VALUES (
    1, expected_database, expected_server_address, expected_server_port,
    environment_value, clock_timestamp()
  )
  ON CONFLICT ("id") DO UPDATE SET
    "databaseName" = EXCLUDED."databaseName",
    "serverAddress" = EXCLUDED."serverAddress",
    "serverPort" = EXCLUDED."serverPort",
    "environment" = EXCLUDED."environment",
    "registeredAt" = EXCLUDED."registeredAt";
END;

DECLARE
  effective_caller TEXT := current_setting('role', true);
BEGIN
  IF current_setting('session_replication_role') IS DISTINCT FROM 'origin' THEN
    RAISE EXCEPTION 'Phase 7 facades require session_replication_role=origin.'
      USING ERRCODE = '42501';
  END IF;
  IF effective_caller IS NULL OR effective_caller = 'none' THEN
    effective_caller := session_user;
  END IF;
  IF effective_caller IS DISTINCT FROM required_role
    AND NOT (
      effective_caller = 'nihongo_app'
      AND required_role IN ('nihongo_auth_gateway', 'nihongo_erasure_worker')
    ) THEN
    RAISE EXCEPTION 'Caller role % is not authorized for this facade.',
      effective_caller USING ERRCODE = '42501';
  END IF;
END;

DECLARE
  capability "Phase7DatabaseCapability"%ROWTYPE;
  actual_address INET := inet_server_addr();
  actual_port INTEGER := inet_server_port();
BEGIN
  SELECT * INTO capability
  FROM "Phase7DatabaseCapability"
  WHERE "id" = 1;
  IF capability."id" IS NULL
    OR capability."databaseName" <> current_database()
    OR capability."serverAddress" IS DISTINCT FROM actual_address
    OR capability."serverPort" IS DISTINCT FROM actual_port
    OR (environment_value IS NOT NULL
      AND capability."environment" IS DISTINCT FROM environment_value)
    OR (capability."environment" = 'TEST'
      AND capability."databaseName" !~ '_test$')
    OR (capability."environment" = 'DEVELOPMENT'
      AND capability."databaseName" !~ '_dev$') THEN
    RAISE EXCEPTION 'Phase 7 database capability is absent or stale.'
      USING ERRCODE = '42501';
  END IF;
END;

DECLARE
  effective_caller TEXT := current_setting('role', true);
BEGIN
  IF current_setting('session_replication_role') IS DISTINCT FROM 'origin' THEN
    RAISE EXCEPTION 'Phase 7 runtime requires session_replication_role=origin.'
      USING ERRCODE = '42501';
  END IF;
  IF effective_caller IS NULL OR effective_caller = 'none' THEN
    effective_caller := session_user;
  END IF;
  IF effective_caller NOT IN ('nihongo_app', 'nihongo_auth_gateway') THEN
    RAISE EXCEPTION 'Caller role % is not a Phase 7 runtime role.',
      effective_caller USING ERRCODE = '42501';
  END IF;
  PERFORM "phase7_require_database_capability"(NULL);
  IF NOT EXISTS (
    SELECT 1 FROM "AuthIssuerActivation"
    WHERE "id" = 1 AND "legacyIssuerDisabled"
  ) THEN
    RAISE EXCEPTION 'Phase 7 V1 issuer activation is incomplete.'
      USING ERRCODE = '42501';
  END IF;
  RETURN true;
END;

DECLARE target_user "User"%ROWTYPE; target_id UUID; event_time TIMESTAMPTZ(3) := clock_timestamp();
BEGIN
  PERFORM "phase7_require_caller_role"('nihongo_auth_gateway');
  PERFORM "phase7_require_runtime_ready"();
  IF provider_id IS NULL OR provider_id NOT IN ('apple','google')
    OR provider_subject IS NULL OR char_length(provider_subject) NOT BETWEEN 1 AND 255
    OR contact_email IS NULL OR char_length(contact_email) NOT BETWEEN 3 AND 320
    OR display_name IS NULL OR char_length(display_name) NOT BETWEEN 1 AND 80 THEN
    RAISE EXCEPTION 'Malformed verified SSO identity.' USING ERRCODE = '22023';
  END IF;
  -- Serialize the exact provider/sub pair; unique(providerId,accountId) remains authoritative.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('nihongo:sso:' || provider_id || ':' || provider_subject, 0));
  SELECT account."userId" INTO target_id FROM "Account" AS account
    WHERE account."providerId" = provider_id AND account."accountId" = provider_subject;
  IF target_id IS NULL THEN
    -- Email is contact data, never proof for merging or inheriting ADMIN authority.
    IF EXISTS (SELECT 1 FROM "User" WHERE lower("email") = lower(contact_email)) THEN
      RETURN jsonb_build_object('outcome','TRANSITION_REQUIRED');
    END IF;
    target_id := public.gen_random_uuid();
    BEGIN
      INSERT INTO "User" ("id","name","email","emailVerified","role","accountStatus","authorityGeneration","createdAt","updatedAt")
      VALUES (target_id,display_name,lower(contact_email),true,'USER','ACTIVE',1,event_time,event_time);
      INSERT INTO "Account" ("id","accountId","providerId","userId","createdAt","updatedAt")
      VALUES (public.gen_random_uuid(),provider_subject,provider_id,target_id,event_time,event_time);
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('outcome','IDENTITY_CONFLICT');
    END;
  END IF;
  SELECT * INTO target_user FROM "User" WHERE "id" = target_id FOR UPDATE;
  IF target_user."id" IS NULL OR target_user."accountStatus" <> 'ACTIVE' OR target_user."deletedAt" IS NOT NULL THEN
    RETURN jsonb_build_object('outcome','ACCOUNT_UNAVAILABLE');
  END IF;
  RETURN jsonb_build_object('outcome','RESOLVED','userId',target_user."id",'authorityGeneration',target_user."authorityGeneration",'role',target_user."role",'accountStatus',target_user."accountStatus");
END;

DECLARE
  session_count INTEGER;
  note_count INTEGER;
BEGIN
  IF pg_catalog.current_database() !~ '_test$'
    OR SESSION_USER <> 'nihongo_test_phase7_migration_login'
    OR pg_catalog.current_setting('role', true) <> 'nihongo_phase7_migration'
    OR pg_catalog.current_setting('session_replication_role') <> 'origin'
    OR target_ids IS NULL OR pg_catalog.cardinality(target_ids) < 1
    OR pg_catalog.cardinality(target_ids) > 500
    OR EXISTS (SELECT 1 FROM pg_catalog.unnest(target_ids) AS ids(id) WHERE id IS NULL)
    OR (SELECT pg_catalog.count(DISTINCT id) FROM pg_catalog.unnest(target_ids) AS ids(id)) <> pg_catalog.cardinality(target_ids)
  THEN RAISE EXCEPTION 'V1 retirement facade requires bounded TEST targets.' USING ERRCODE = '42501'; END IF;

  PERFORM 1 FROM "StudySession" AS session WHERE session."id" = ANY(target_ids)
    ORDER BY session."id" FOR UPDATE;
  SELECT count(*) INTO session_count FROM "StudySession" AS session
    WHERE session."id" = ANY(target_ids) AND session."practiceContractVersion" = 1
      AND session."status" <> 'IN_PROGRESS'
      AND ((session."userId" IS NOT NULL AND session."guestPrincipalId" IS NULL)
        OR (session."userId" IS NULL AND session."guestPrincipalId" IS NOT NULL))
      AND NOT EXISTS (SELECT 1 FROM "StudySession" AS retry WHERE retry."retryOfStudySessionId" = session."id");
  IF session_count <> pg_catalog.cardinality(target_ids) THEN
    RAISE EXCEPTION 'V1 retirement target changed or has a retry.' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM "WrongNote" AS note WHERE EXISTS (
    SELECT 1 FROM "ReviewEvent" AS event WHERE event."wrongNoteId" = note."id"
      AND event."studySessionId" = ANY(target_ids)) ORDER BY note."id" FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM "ReviewEvent" AS event JOIN "WrongNote" AS note ON note."id" = event."wrongNoteId"
    WHERE event."studySessionId" = ANY(target_ids) AND (
      EXISTS (SELECT 1 FROM "UserMemo" AS memo WHERE memo."wrongNoteId" = note."id")
      OR EXISTS (SELECT 1 FROM "ReviewEvent" AS other WHERE other."wrongNoteId" = note."id"
        AND (other."studySessionId" IS NULL OR NOT (other."studySessionId" = ANY(target_ids))))
    )
  ) THEN RAISE EXCEPTION 'V1 retirement review history is shared or has a memo.' USING ERRCODE = '23514'; END IF;

  DELETE FROM "WrongNote" AS note WHERE EXISTS (
    SELECT 1 FROM "ReviewEvent" AS event WHERE event."wrongNoteId" = note."id"
      AND event."studySessionId" = ANY(target_ids));
  GET DIAGNOSTICS note_count = ROW_COUNT;
  DELETE FROM "StudySession" AS session WHERE session."id" = ANY(target_ids)
    AND session."practiceContractVersion" = 1
    AND NOT EXISTS (SELECT 1 FROM "StudySession" AS retry WHERE retry."retryOfStudySessionId" = session."id")
    AND NOT EXISTS (SELECT 1 FROM "ReviewEvent" AS event WHERE event."studySessionId" = session."id");
  GET DIAGNOSTICS session_count = ROW_COUNT;
  IF session_count <> pg_catalog.cardinality(target_ids) THEN
    RAISE EXCEPTION 'V1 retirement target changed during cleanup.' USING ERRCODE = '40001';
  END IF;
  RETURN QUERY SELECT session_count, note_count;
END;

DECLARE
  database_name TEXT := current_database();
  database_owner TEXT;
  legacy_login TEXT := CASE
    WHEN current_database() ~ '_test$' THEN 'nihongo_test_legacy_app_login'
    WHEN current_database() ~ '_dev$' THEN 'nihongo_development_legacy_app_login'
    ELSE NULL
  END;
BEGIN
  -- #504 P7 PR4c-2: called only by phase7_activate_v1_issuer, which requires
  -- the migration operator.
  IF COALESCE(NULLIF(current_setting('role', true), 'none'), session_user) <> 'nihongo_phase7_migration' THEN
    RAISE EXCEPTION 'Legacy CONNECT revoke requires active V1 activation.'
      USING ERRCODE = '42501';
  END IF;
  SELECT owner_role.rolname INTO database_owner
  FROM pg_catalog.pg_database AS database_row
  JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = database_row.datdba
  WHERE database_row.datname = database_name;
  IF database_owner IS DISTINCT FROM CURRENT_USER OR legacy_login IS NULL THEN
    RAISE EXCEPTION 'Legacy CONNECT revoke requires the migration DB owner.'
      USING ERRCODE = '42501';
  END IF;
  EXECUTE pg_catalog.format(
    'REVOKE ALL PRIVILEGES ON DATABASE %I FROM %I',
    database_name,
    legacy_login
  );
END;

BEGIN
  -- This function runs as its caller: current_user is nihongo_app only for a
  -- direct API statement.
  IF current_user <> 'nihongo_app' THEN RETURN NEW; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "User"
    WHERE "id" = NEW."userId" AND "accountStatus" = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'SSO erasure request requires an active User.'
      USING ERRCODE = '42501';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'provider', p.provider, 'status', 'PENDING'
    ) ORDER BY p.provider), '[]'::jsonb)
  INTO NEW."providerCleanup"
  FROM (
    SELECT DISTINCT "providerId" AS provider FROM "Account"
    WHERE "userId" = NEW."userId" AND "providerId" IN ('apple', 'google')
  ) AS p;
  NEW."appStatus" := 'DELETION_PENDING';
  NEW."createdAt" := clock_timestamp();
  NEW."receiptExpiresAt" := clock_timestamp() + INTERVAL '1 day';
  NEW."completedAt" := NULL;
  NEW."leaseToken" := NULL;
  NEW."leaseExpiresAt" := NULL;
  NEW."activeProvider" := NULL;
  RETURN NEW;
END;

DECLARE
  legacy_disabled BOOLEAN;
  legacy_login TEXT := CASE
    WHEN current_database() ~ '_test$' THEN 'nihongo_test_legacy_app_login'
    WHEN current_database() ~ '_dev$' THEN 'nihongo_development_legacy_app_login'
    ELSE NULL
  END;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- #504 P7 PR4a: an erased User's Accounts go with the User delete, which
    -- User_limit_erasure_delete accepts only for a confirmed erasure.
    IF OLD."providerId" = 'credential'
      AND EXISTS (SELECT 1 FROM "User" WHERE "id" = OLD."userId") THEN
      RAISE EXCEPTION 'Credential Account delete is erasure-only.'
        USING ERRCODE = '42501';
    END IF;
    -- #504 P7 PR5a: an API SSO Account unlink revokes every Session of its
    -- User, as phase7_unlink_sso_account did: the User trigger accepts this
    -- generation step, records the revocation and deletes the Sessions. An
    -- erasure removes Accounts with the User row.
    IF COALESCE(NULLIF(current_setting('role', true), 'none'), session_user) = 'nihongo_app'
      AND OLD."providerId" IN ('apple', 'google')
      AND EXISTS (SELECT 1 FROM "User" WHERE "id" = OLD."userId") THEN
      UPDATE "User" SET "authorityGeneration" = "authorityGeneration" + 1
      WHERE "id" = OLD."userId";
    END IF;
    RETURN OLD;
  END IF;
  IF NEW."id" <> OLD."id" OR NEW."accountId" <> OLD."accountId"
    OR NEW."providerId" <> OLD."providerId" OR NEW."userId" <> OLD."userId"
    OR NEW."createdAt" <> OLD."createdAt" THEN
    RAISE EXCEPTION 'Account identity is insert-only.' USING ERRCODE = '23514';
  END IF;
  IF OLD."providerId" = 'credential' THEN
    IF SESSION_USER = legacy_login THEN
      SELECT "legacyIssuerDisabled" INTO legacy_disabled
      FROM "AuthIssuerActivation" WHERE "id" = 1 FOR SHARE;
      IF FOUND AND legacy_disabled IS NOT DISTINCT FROM false
        AND (to_jsonb(NEW) - 'password' - 'updatedAt') =
            (to_jsonb(OLD) - 'password' - 'updatedAt') THEN
        RETURN NEW;
      END IF;
    END IF;
    RAISE EXCEPTION 'Credential Account update requires owned password authority.'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;

